export interface Base { readonly id: string; optional?: number; }
export interface Derived extends Base { value: boolean; }
export type Alias = Derived;
export type Combined = Derived & { tag: "x" };
export function overload(value: string): string;
export function overload(value: number): number;
export function overload(value: string | number): string | number { return value; }
export interface Box<T extends Base = Derived> { value: T; }
export type NumberBox = Box<Derived>;
import type { Missing } from "./deliberately-absent.js";
export type Broken = Missing;
